INSERT INTO jangdans (id, name, pattern, default_bpm, bpm_unit, source) VALUES
  (1, '세마치', '{"beats":["떵","","","떵","","덕","쿵","덕",""],"group":[3,3,3]}', 96, 'DOTTED_QUARTER', '구음: e-국악아카데미 세마치 장단(9/8, 떵 떵 덕 쿵 덕, ♩.=90~110). BPM: 기획 S15P31E102-141'),
  (2, '굿거리', '{"beats":["떵","","기덕","쿵","더러러러","","쿵","","기덕","쿵","더러러러",""],"group":[3,3,3,3]}', 66, 'DOTTED_QUARTER', '구음: e-국악아카데미 굿거리 장단(12/8, 떵기덕 쿵 더러러러 쿵기덕 쿵 더러러러, ♩.=66~90). BPM: 기획 S15P31E102-141'),
  (3, '중모리', '{"beats":["떵","","덕","쿵","덕기","덕덕","쿵","쿵","덕","쿵","덕기","덕덕"],"group":[6,6]}', 88, 'QUARTER', '구음: e-국악아카데미 중모리 장단(12/4, 앞 6박·뒤 6박, ♩=72~84). BPM: 기획 S15P31E102-141. 88은 이 자료의 범위보다 빠름');
